 public sealed partial class OutputPresetR14 {public AnimationBanksR16 BanksR16;public Dictionary<string,string> BankAssetsR16=new Dictionary<string,string>();}
 static class BankPresetsR16 {
  internal static string Folder {get{return Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"../Assets"));}}
  internal static void Pack(AnimationBanksR16 banks,Dictionary<string,string> assets,string folder){foreach(var b in banks.Items)if(!string.IsNullOrWhiteSpace(b.Asset)&&!assets.ContainsKey(b.Asset))assets[b.Asset]=Convert.ToBase64String(File.ReadAllBytes(Store934.MediaPath(folder,b.Asset)));}
  internal static void Unpack(AnimationBanksR16 banks,Dictionary<string,string> assets,string folder){banks.Validate();foreach(var b in banks.Items){if(string.IsNullOrWhiteSpace(b.Asset))continue;string data;if(!assets.TryGetValue(b.Asset,out data))throw new InvalidDataException("Banque absente du preset : "+b.Name);string ext=Path.GetExtension(b.Asset).ToLowerInvariant();if(!new[]{".gif",".png",".mp4"}.Contains(ext))throw new InvalidDataException("Format de banque non pris en charge.");byte[] bytes=Convert.FromBase64String(data);if(File.Exists(b.Asset)&&File.ReadAllBytes(b.Asset).SequenceEqual(bytes))continue;string hash;using(var sha=SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","");Directory.CreateDirectory(folder);string path=Path.Combine(folder,hash+ext);if(!File.Exists(path))File.WriteAllBytes(path,bytes);b.Asset=path;}}
  internal static OutputPresetR14 Preset(bool voice){var e=new Effect936{Kind=EffectKind936.Animation,Size=45,X=50,Y=50,Opacity15=100,Release=0};e.BanksR16=new AnimationBanksR16{Enabled=true,VoiceMouth=voice,Select=voice?BankSelectR16.Vélocité:BankSelectR16.Aléatoire,Gate=false,Loop=false,Fps=8,Hysteresis=0,CompleteR18=!voice};for(int i=0;i<3;i++)e.BanksR16.Items.Add(new AnimationBankR16{Name="Banque "+(i+1),Min=i==0?0:i==1?50:90,Max=i==0?49:i==1?89:127});var p=OutputPresetsR14.Pack(e,voice?"Voice to MIDI — 3 banques":"Danse — aléatoire, animation complète",voice?"Any":"Note");p.Branch="Animation";return p;}
  internal static void Add(List<OutputPresetR14> list){list.Add(Preset(true));list.Add(Preset(false));}

 }
